#pragma once
#include <Arduino.h>

// Sequential, nonblocking USB/BLE HID macro that types a prebuilt PicoSwitch
// Civ7 chat bootstrap read from Cardputer microSD. The file is NOT the
// upstream JS itself; it is the chat-XSS line transport generated by compress.js.
namespace CivMacro {
bool inspect(const char* path = "/civswitch/bootstrap.txt");
bool start();
bool testA();
void tick();
void abort(const String &reason);
bool running();
bool completed();
int percent();
uint32_t lineNumber();
uint32_t totalLines();
String status();
} // namespace CivMacro
